import os, pty, sys, time, select, fcntl, termios, struct, signal

def run(args, keys, rows=30, cols=100, settle=0.5, out=None, env_extra=None, delay=0.05):
    pid, fd = pty.fork()
    if pid == 0:
        env = dict(os.environ)
        env['TERM'] = 'xterm-256color'
        env['COLUMNS'] = str(cols); env['LINES'] = str(rows)
        if env_extra: env.update(env_extra)
        os.execvpe(args[0], args, env)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    buf = b''
    def pump(t):
        end = time.time()+t
        nonlocal buf
        while time.time() < end:
            r,_,_ = select.select([fd], [], [], 0.05)
            if r:
                try:
                    d = os.read(fd, 65536)
                except OSError:
                    return False
                if not d: return False
                buf += d
        return True
    pump(settle)
    for k in keys:
        if isinstance(k, float) or isinstance(k, int):
            pump(k); continue
        os.write(fd, k if isinstance(k,bytes) else k.encode())
        pump(delay)
    pump(settle)
    try:
        os.kill(pid, signal.SIGKILL)
    except Exception: pass
    try: os.waitpid(pid, 0)
    except Exception: pass
    if out:
        open(out,'wb').write(buf)
    return buf

if __name__ == '__main__':
    pass
