import sys, time, re
sys.path.insert(0,'/tmp/rec')
from inter import Session

def parse(lines):
    d={}
    m=re.search(r'Lesson #(\d+)', lines[3]); d['lesson']=int(m.group(1)) if m else None
    m=re.search(r'✔: (\d+), ✘: (\d+)', lines[3])
    if m: d['ok']=int(m.group(1)); d['bad']=int(m.group(2))
    d['row6']=lines[6][1:-1] if len(lines)>6 else None
    d['row7']=lines[7][1:-1] if len(lines)>7 else None
    # wpm/acc rows: find by content
    for l in lines:
        if 'WPM' in l:
            d['wpmrow']=l
            m=re.search(r'need >= *(-?\d+)WPM, *avg. *(-?\d+)WPM, *last *(-?\d+)WPM', l)
            if m: d['need_w'],d['avg_w'],d['last_w']=[int(x) for x in m.groups()]
        if '% Acc' in l:
            d['accrow']=l
            m=re.search(r'need >= *(-?\d+)% Acc, *avg. *(-?\d+)% Acc, *last *(-?\d+)% Acc', l)
            if m: d['need_a'],d['avg_a'],d['last_a']=[int(x) for x in m.groups()]
    return d

def lesson_text(lines):
    return lines[6][1:-1].strip()

class S(Session):
    def st(self):
        return parse(self.lines())
